#include <QtCore/QTimer>

namespace Luckgram {
namespace {

// Kept in the binary so CI can check the release exe does not contain it.
constexpr auto kMarker = "LuckgramCiTestLogin";
constexpr auto kTestDc = 2;
constexpr auto kStartDelay = 3000;

void Log(const QString &text) {
	LOG(("%1: %2").arg(QString::fromLatin1(kMarker), text));
}

struct Flow {
	not_null<Main::Account*> account;
	MTP::Sender api;
	QString phone;
	QByteArray phoneHash;
	QByteArray termsId;
	Fn<void(bool)> done;

	explicit Flow(not_null<Main::Account*> account)
	: account(account)
	, api(&account->mtp()) {
	}
};

void Finish(std::shared_ptr<Flow> flow, bool ok) {
	if (const auto done = base::take(flow->done)) {
		done(ok);
	}
}

void CreateSession(std::shared_ptr<Flow> flow, const MTPUser &user) {
	const auto account = flow->account;
	account->createSession(user);
	account->local().writeMtpData();
	if (!flow->termsId.isEmpty()) {
		account->session().api().acceptTerms(bytes::make_span(flow->termsId));
	}
	Log(u"signed in"_q);
	Finish(flow, true);
}

void SignUp(std::shared_ptr<Flow> flow);

void Authorized(
		std::shared_ptr<Flow> flow,
		const MTPauth_Authorization &result) {
	result.match([&](const MTPDauth_authorization &data) {
		CreateSession(flow, data.vuser());
	}, [&](const MTPDauth_authorizationSignUpRequired &data) {
		if (const auto terms = data.vterms_of_service()) {
			flow->termsId = terms->data().vid().c_dataJSON().vdata().v;
		}
		SignUp(flow);
	});
}

void Fail(std::shared_ptr<Flow> flow, const QString &step, const MTP::Error &error) {
	Log(step + u" failed: "_q + error.type());
	Finish(flow, false);
}

void SignUp(std::shared_ptr<Flow> flow) {
	flow->api.request(MTPauth_SignUp(
		MTP_flags(0),
		MTP_string(flow->phone),
		MTP_bytes(flow->phoneHash),
		MTP_string(u"Luckgram"_q),
		MTP_string(u"CI"_q)
	)).done([=](const MTPauth_Authorization &result) {
		Authorized(flow, result);
	}).fail([=](const MTP::Error &error) {
		Fail(flow, u"auth.signUp"_q, error);
	}).send();
}

void SignIn(std::shared_ptr<Flow> flow) {
	const auto code = QString(5, QChar('0' + kTestDc));
	flow->api.request(MTPauth_SignIn(
		MTP_flags(MTPauth_SignIn::Flag::f_phone_code),
		MTP_string(flow->phone),
		MTP_bytes(flow->phoneHash),
		MTP_string(code),
		MTPEmailVerification()
	)).done([=](const MTPauth_Authorization &result) {
		Authorized(flow, result);
	}).fail([=](const MTP::Error &error) {
		Fail(flow, u"auth.signIn"_q, error);
	}).send();
}

void SendCode(std::shared_ptr<Flow> flow) {
	flow->api.request(MTPauth_SendCode(
		MTP_string(flow->phone),
		MTP_int(ApiId),
		MTP_string(ApiHash),
		MTP_codeSettings(
			MTP_flags(0),
			MTPVector<MTPbytes>(),
			MTPstring(),
			MTPBool())
	)).done([=](const MTPauth_SentCode &result) {
		result.match([&](const MTPDauth_sentCode &data) {
			flow->phoneHash = data.vphone_code_hash().v;
			SignIn(flow);
		}, [&](const MTPDauth_sentCodeSuccess &data) {
			Authorized(flow, data.vauthorization());
		}, [&](const MTPDauth_sentCodePaymentRequired &) {
			Log(u"auth.sendCode: payment required"_q);
			Finish(flow, false);
		});
	}).fail([=](const MTP::Error &error) {
		Fail(flow, u"auth.sendCode"_q, error);
	}).send();
}

} // namespace

bool CiTestLoginAvailable() {
	return true;
}

void CiTestLogin(Fn<void(bool)> done) {
	Core::App().domain().addActivated(MTP::Environment::Test);
	const auto account = &Core::App().activeAccount();
	if (account->mtp().environment() != MTP::Environment::Test) {
		Log(u"no test account"_q);
		done(false);
		return;
	}
	auto flow = std::make_shared<Flow>(account);
	flow->phone = u"99966%1%2"_q
		.arg(kTestDc)
		.arg(base::RandomIndex(10000), 4, 10, QChar('0'));
	flow->done = std::move(done);
	Log(u"test number 99966%1XXXX"_q.arg(kTestDc));
	QTimer::singleShot(kStartDelay, qApp, [=] {
		SendCode(flow);
	});
}

} // namespace Luckgram

#else // LUCKGRAM_CI_TEST_LOGIN

namespace Luckgram {

bool CiTestLoginAvailable() {
	return false;
}

void CiTestLogin(Fn<void(bool)> done) {
	done(false);
}

} // namespace Luckgram

#endif // LUCKGRAM_CI_TEST_LOGIN
